using System.IO;
using System.IO.Path;
using Microsoft.Azure;
using Blobstorage = Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Blob;
using Microsoft.Dynamics.Platform.Integration.SharePoint;
using Microsoft.Dynamics.ApplicationPlatform.Services.Instrumentation;
using Microsoft.DynamicsOnline.Infrastructure.Components.SharedServiceUnitStorage;
using Microsoft.Dynamics.AX.Framework.FileManagement;
/// <summary>
/// CB521_ExciseREgister
/// Class used for NAT3040 reporting
/// </summary>
public class METNature3040ReportController extends SrsReportRunController
{
    #define.ExcelExtension('.xlsx')
}

Method.Source:
    /// <summary>
    /// This method is a main method of class
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METNature3040ReportController controller = new METNature3040ReportController();

        if (args.menuItemName() == menuItemActionStr(METNature30Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
        }
        else if (args.menuItemName() == menuItemActionStr(METNature40Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
        }

        controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        controller.parmArgs(args);
        controller.startOperation();
    }

    private void executeReportSiteSpecific()
    {
        Filename                                fileName;
        SRSPrintDestinationSettings             settings;
        System.Byte[]                           reportBytes;
        SRSProxy                                srsProxy;
        SRSReportRunService                     srsReportRunService;
        Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray;
        Map                                     reportParametersMap;
        SRSReportExecutionInfo                  executionInfo;
        METNature3040ReportContract             contract = new METNature3040ReportContract();
        METExciseInformationTable               metExciseInformationTable;
        METInventTable                          metInventTable;
        METTariffItemCodeBase                   metTariffItemCodeBase;
        METNAT3040                              metNat3040;

        METReportRunHistory                     lastSucessfulReportRun;
        TransDateTime                           successfulRunDate;

        try
        {
            ttsbegin;
            
            if (args.menuItemName() == menuItemActionStr(METNature30Report))
            {
                metNat3040 = METNAT3040::NAT30;
                this.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
            }
            else if (args.menuItemName() == menuItemActionStr(METNature40Report))
            {
                metNat3040 = METNAT3040::NAT40;
                this.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
            }

            select firstonly forupdate LastSuccessfulRun from lastSucessfulReportRun
                    where lastSucessfulReportRun.SRSReportName == this.parmReportName() &&
                            lastSucessfulReportRun.SiteSpecific == NoYes::Yes &&
                            lastSucessfulReportRun.Site == '';

            if (!contract.parmFromDate())
            {
                if (!lastSucessfulReportRun)
                {
                    metExciseInformationTable = null;

                    select firstonly CreatedDateTime from metExciseInformationTable
                        order by CreatedDateTime;

                    if (metExciseInformationTable.CreatedDateTime)
                    {
                        contract.parmFromDate(DateTimeUtil::date(metExciseInformationTable.CreatedDateTime));
                        contract.parmLastRunDateTime(metExciseInformationTable.CreatedDateTime);
                    }
                    else
                    {
                        contract.parmFromDate(DateTimeUtil::date(DateTimeUtil::minValue()));
                        contract.parmLastRunDateTime(DateTimeUtil::minValue());
                    }
                }
                else
                {
                    contract.parmLastRunDateTime(lastSucessfulReportRun.LastSuccessfulRun);
                    contract.parmFromDate(DateTimeUtil::date(DateTimeUtil::addSeconds(lastSucessfulReportRun.LastSuccessfulRun, 1)));
                }
            }
                
            if (contract.parmCPI())
            {
                contract.parmToDate(DateTimeUtil::date(DateTimeUtil::utcNow()));
            }
            else
            {
                if (!contract.parmToDate())
                {
                    contract.parmToDate(DateTimeUtil::date(DateTimeUtil::utcNow()) - 1);
                }
            }
            successfulRunDate = DateTimeUtil::newDateTime(contract.parmToDate(), 86399);

            contract.parmMETNat3040(metNat3040);

            FromDateTime fromDateTime = DateTimeUtil::newDateTime(contract.parmFromDate(), 0);
            ToDateTime toDateTime = DateTimeUtil::newDateTime(contract.parmToDate(), 86399);

            metExciseInformationTable = null;
            METExciseRegisterOriginTypes        originType;

            while select SiteId from metExciseInformationTable
                group by SiteId
                where metExciseInformationTable.CreatedDateTime >= fromDateTime
                   && metExciseInformationTable.CreatedDateTime <= toDateTime
                exists join metInventTable
                    where metInventTable.ItemId == metExciseInformationTable.ItemId
                        exists join metTariffItemCodeBase
                            where metTariffItemCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
                                && metTariffItemCodeBase.NAT3040 == metNat3040
                        exists join originType
                            where originType.ReferenceId == metExciseInformationTable.InventTransType
                               && originType.UpdateNAT3040 == NoYes::Yes
            {
                srsReportRunService = new SrsReportRunService();
                reportBytes = new System.Byte[0]();
                executionInfo = new SRSReportExecutionInfo();

                contract.parmSite(metExciseInformationTable.SiteId); //setting site id for current iteration
                contract.parmSiteName(InventSite::find(metExciseInformationTable.SiteId).Name);
                contract.parmSiteSpecific(true);

                if (metNat3040 == METNAT3040::NAT30)
                {
                    fileName = strFmt("@MET:Nature30report", InventSite::find(metExciseInformationTable.SiteId).Name ,contract.parmFromDate(), contract.parmToDate());
                }
                else if (metNat3040 == METNAT3040::NAT40)
                {
                    fileName = strFmt("@MET:Nature40Report", InventSite::find(metExciseInformationTable.SiteId).Name ,contract.parmFromDate(), contract.parmToDate());
                }
                fileName = strReplace(fileName, "/", "-") + #ExcelExtension;

                this.parmReportContract().parmRdpContract(contract);

                settings = this.parmReportContract().parmPrintSettings();
                settings.printMediumType(SRSPrintMediumType::File);
                settings.fileName(fileName);
                settings.fileFormat(SRSReportFileFormat::Excel);

                this.parmReportContract().parmReportServerConfig(SRSConfiguration::getDefaultServerConfiguration());
                this.parmReportContract().parmReportExecutionInfo(executionInfo);

                srsReportRunService.getReportDataContract(this.parmreportcontract().parmReportName());
                srsReportRunService.preRunReport(this.parmreportcontract());

                reportParametersMap = srsReportRunService.createParamMapFromContract(this.parmReportContract());
                parameterValueArray = SrsReportRunUtil::getParameterValueArray(reportParametersMap);
                srsProxy =SRSProxy::constructWithConfiguration(this.parmReportContract().parmReportServerConfig());
                reportBytes = srsproxy.renderReportToByteArray(this.parmreportcontract().parmreportpath(),
                                                    parameterValueArray,
                                                    settings.fileFormat(),
                                                    settings.deviceinfo());

                System.IO.MemoryStream  mstream = new System.IO.MemoryStream(reportBytes);

                mstream.Seek(0, System.IO.SeekOrigin::Begin);
                
                METSharePointHelper::saveToSharepoint(mstream, fileName, VendParameters::find().METNAT3040DocuTypeId);

                if (!contract.parmNat30Number())
                {
                    if (lastSucessfulReportRun)
                    {
                        lastSucessfulReportRun.LastSuccessfulRun = successfulRunDate;
                        lastSucessfulReportRun.update();
                    }
                    else
                    {
                        lastSucessfulReportRun.SRSReportName = this.parmReportName();
                        lastSucessfulReportRun.LastSuccessfulRun = successfulRunDate;
                        lastSucessfulReportRun.SiteSpecific = NoYes::Yes;
                        lastSucessfulReportRun.Site = '';
                        lastSucessfulReportRun.insert();
                    }
                }
            }
            ttscommit;
        }
        catch (Exception::Error)
        {
            throw error("@MET:SharepointError");
        }

    }

    /// <summary>
    /// Method used to change the behaviour of report if it is in batch
    /// </summary>
    protected void preRunModifyContract()
    {
        METNature3040ReportContract             contract =  this.parmReportContract().parmRdpContract() as METNature3040ReportContract;

        //If report is executed in batch then it should create excel file and upload to the sharepoint path
        if (this.isInBatch() && !contract.parmSiteSpecific())
        {
            Filename                                fileName;
            SRSPrintDestinationSettings             settings;
            System.Byte[]                           reportBytes = new System.Byte[0]();
            SRSProxy                                srsProxy;
            SRSReportRunService                     srsReportRunService = new SrsReportRunService();
            Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray;
            Map                                     reportParametersMap;
            SRSReportExecutionInfo                  executionInfo = new SRSReportExecutionInfo();
            METExciseInformationTable               metExciseInformationTable;
            METNAT3040                              metNat3040;

            METReportRunHistory                     lastSucessfulReportRun;
            TransDateTime                           successfulRunDate;     

            try
            {
                ttsbegin;
            
                if (args.menuItemName() == menuItemActionStr(METNature30Report))
                {
                    metNat3040 = METNAT3040::NAT30;
                    this.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
                }
                else if (args.menuItemName() == menuItemActionStr(METNature40Report))
                {
                    metNat3040 = METNAT3040::NAT40;
                    this.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
                }

                select firstonly forupdate LastSuccessfulRun from lastSucessfulReportRun
                        where lastSucessfulReportRun.SRSReportName == this.parmReportName() &&
                              lastSucessfulReportRun.SiteSpecific == NoYes::No &&
                              lastSucessfulReportRun.Site == contract.parmSite();

                contract = new METNature3040ReportContract();

                if (!contract.parmFromDate())
                {
                    if (!lastSucessfulReportRun)
                    {
                        contract.parmFromDate(DateTimeUtil::date(DateTimeUtil::minValue()));
                    }
                    else
                    {
                        contract.parmFromDate(DateTimeUtil::date(DateTimeUtil::addSeconds(lastSucessfulReportRun.LastSuccessfulRun, 1)));
                    }
                }
                
                if (contract.parmCPI())
                {
                    contract.parmToDate(DateTimeUtil::date(DateTimeUtil::utcNow()));
                }
                else
                {
                    if (!contract.parmToDate())
                    {
                        contract.parmToDate(DateTimeUtil::date(DateTimeUtil::utcNow()) - 1);
                    }
                }
                successfulRunDate = DateTimeUtil::newDateTime(contract.parmToDate(), 86399);

                contract.parmMETNat3040(metNat3040);

                if (metNat3040 == METNAT3040::NAT30)
                {
                    if (contract.parmNat30Number())
                    {
                        fileName = strFmt("@MET:Nat30Reportxlsx", metExciseInformationTable.Nat3040ReportNumber);
                    }
                    else if (contract.parmSite())
                    {
                        fileName = strFmt("@MET:Nature30report", InventSite::find(contract.parmSite()).Name ,contract.parmFromDate(), contract.parmToDate());
                        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
                    }
                    else
                    {
                        fileName = strFmt("@MET:NationalNat30Report", contract.parmFromDate(), contract.parmToDate());
                        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
                    }
                }
                else if (metNat3040 == METNAT3040::NAT40)
                {
                    if (contract.parmNat30Number())
                    {
                        fileName = strFmt("@MET:Nat40Reportxlsx", metExciseInformationTable.Nat3040ReportNumber);
                    }
                    else if (contract.parmSite())
                    {
                        fileName = strFmt("@MET:Nature40Report", InventSite::find(contract.parmSite()).Name ,contract.parmFromDate(), contract.parmToDate());
                        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
                    }
                    else
                    {
                        fileName = strFmt("@MET:NationalNat40Report", contract.parmFromDate(), contract.parmToDate());
                        fileName = strReplace(fileName, "/", "-") + #ExcelExtension;
                    }
                }

                this.parmReportContract().parmRdpContract(contract);

                settings = this.parmReportContract().parmPrintSettings();
                settings.printMediumType(SRSPrintMediumType::File);
                settings.fileName(fileName);
                settings.fileFormat(SRSReportFileFormat::Excel);

                this.parmReportContract().parmReportServerConfig(SRSConfiguration::getDefaultServerConfiguration());
                this.parmReportContract().parmReportExecutionInfo(executionInfo);

                srsReportRunService.getReportDataContract(this.parmreportcontract().parmReportName());
                srsReportRunService.preRunReport(this.parmreportcontract());

                reportParametersMap = srsReportRunService.createParamMapFromContract(this.parmReportContract());
                parameterValueArray = SrsReportRunUtil::getParameterValueArray(reportParametersMap);
                srsProxy =SRSProxy::constructWithConfiguration(this.parmReportContract().parmReportServerConfig());
                reportBytes = srsproxy.renderReportToByteArray(this.parmreportcontract().parmreportpath(),
                                                parameterValueArray,
                                                settings.fileFormat(),
                                                settings.deviceinfo());

                System.IO.MemoryStream  mstream = new System.IO.MemoryStream(reportBytes);

                mstream.Seek(0, System.IO.SeekOrigin::Begin);

                METSharePointHelper::saveToSharepoint(mstream, fileName, VendParameters::find().METNAT3040DocuTypeId);

                if (!contract.parmNat30Number())
                {
                    if (lastSucessfulReportRun)
                    {   lastSucessfulReportRun.LastSuccessfulRun = successfulRunDate;
                        lastSucessfulReportRun.update();
                    }
                    else
                    {
                        lastSucessfulReportRun.SRSReportName = this.parmReportName();
                        lastSucessfulReportRun.LastSuccessfulRun = successfulRunDate;
                        lastSucessfulReportRun.SiteSpecific = NoYes::No;
                        lastSucessfulReportRun.Site = contract.parmSite();
                        lastSucessfulReportRun.insert();
                    }
                }

                ttscommit;
            }
            catch (Exception::Error)
            {
                throw error("@MET:SharepointError");
            }
        }
        else if (this.isInBatch() && contract.parmSiteSpecific())
        {
            this.executeReportSiteSpecific();
        }
        else
        {
            if (contract.parmNat30Number())
            {
                contract.parmFromDate(today());
                contract.parmToDate(today());
                contract.parmLastRunDateTime(DateTimeUtil::newDateTime(today() - 1, 86399));
            }
            super();
        }
    }

    /// <summary>
    /// Not to load last user interaction values
    /// </summary>
    /// <param name = "_loadFromSysLastValue">Boolean reference</param>
    /// <returns>Boolean</returns>
    public boolean parmLoadFromSysLastValue(boolean _loadFromSysLastValue = loadFromSysLastValue)
    {
        return false;
    }

